library(ks)
library(Matrix)
source(file.path(commandArgs(TRUE)[1], 'R', 'kde.R'))
set.seed(42)
x<-matrix(rnorm(80*2),80,2);w<-rpois(80,4)
dens<-calculate_density(w,x,method='wkde',map=FALSE)
write.table(x,'coordinates.csv',sep=',',row.names=FALSE,col.names=FALSE)
write.table(w,'weights.csv',sep=',',row.names=FALSE,col.names=FALSE)
write.table(c(hpi(x[,1]),hpi(x[,2])),'bandwidth.csv',sep=',',row.names=FALSE,col.names=FALSE)
write.table(as.matrix(dens$z),'grid.csv',sep=',',row.names=FALSE,col.names=FALSE)
write.table(get_dens(x,dens,'wkde'),'cells.csv',sep=',',row.names=FALSE,col.names=FALSE)
